import re

def evaluate(output: str, inputs: dict) -> bool:
    # Strict interpretation: each of the six keys must appear exactly once as a
    # bullet-list label ("- key: value"), using the wording from the prompt
    # (minor allowed variants: optional suffix text from the prompt, exam vs
    # examination, follow-up vs follow up), with a non-empty value (N/A ok).
    if not isinstance(output, str) or not output.strip():
        return False

    labels = {
        "chief complaint": r"chief complaint",
        "history of present illness": r"history of present illness",
        "physical examination": r"physical exam(?:ination)?",
        "symptoms": r"symptoms(?: experienced by the patient)?",
        "new medications": r"new medications(?: prescribed or changed)?(?:,? including dosages)?(?: \(n/a if not provided\))?",
        "follow-up instructions": r"follow[- ]?up instructions(?: \(n/a if not provided\))?",
    }
    found = {k: 0 for k in labels}

    for raw in output.splitlines():
        line = raw.replace("**", "").replace("__", "").strip()
        line = line.replace("–", "-").replace("—", "-")
        line = re.sub(r"\s+", " ", line).lower()
        m = re.match(r"^(?:[-*•]|\d+[.)])\s+(.*)$", line)
        if not m:
            continue
        body = m.group(1).strip()
        for k, pat in labels.items():
            mm = re.match(r"^" + pat + r"\s*:\s*(\S.*)?$", body)
            if mm and mm.group(1):
                found[k] += 1
                break

    return all(c == 1 for c in found.values())
